templates.template:
.wp_post-container { padding: 7px 10px; width: 100%; }

.wp_post-image {
    display: block;
    height: auto;
    max-width: 100%;
}

.wp_post-title {
    margin-bottom: 3px;
    margin-top: 0;
}

.wp_post-meta { font-size: @xf-fontSizeSmall; }

.wp_product-price { margin-bottom: 5px; }

.block-wp .structItemContainer {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
}

.p-body-sidebar .wp_post-container:not(:last-child) { border-bottom: 1px solid @xf-borderColor; }

@media all and (min-width: 575px) {
    .p-body-content .wp_post-container {
        align-items: center;
        display: flex;
        flex: 1 1 50%;
        gap: 10px;
        max-width: 50%;
    }
    .p-body-content .wp_post-thumbnail { flex: 1 35%; }
    .p-body-content .wp_post-content { flex: 1 65%; }
}

@media all and (min-width: 750px) {
    .p-body-content .wp_post-container { flex: 1 1 33%; }
}
